#include "RecipeSupport.hpp"
namespace chronontemplate::modern_short_phrase {
ShortPhraseDefinition scrambleReveal(){using namespace detail;auto d=make("short_phrase_product_scramble_reveal","Scramble Reveal","HYPERFRAMES",90,{}, {},98.f);d.drawMainPhrase=false;const std::string target="HYPERFRAMES";const std::string pool="ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789#$%&*+?<>";std::vector<std::string> rows;for(int step=0;step<static_cast<int>(target.size());++step){std::string row=target;for(int col=step;col<static_cast<int>(target.size());++col)row[static_cast<std::size_t>(col)]=pool[static_cast<std::size_t>((step*17+col*29+13)%static_cast<int>(pool.size()))];rows.push_back(std::move(row));}for(int i=0;i<static_cast<int>(rows.size());++i){int start=3+i*8,end=start+8;std::vector<PhraseTrack> tracks;if(i==0)tracks.push_back(t("opacity",{{0,1.f},{end,0.f},{194,0.f},{209,0.f}},"linear"));else tracks.push_back(t("opacity",{{0,0.f},{start,0.f},{start+2,1.f},{end,0.f},{194,0.f},{209,0.f}},"linear"));d.textOverlays.push_back(overlay(("decode_"+std::to_string(i)).c_str(),rows[static_cast<std::size_t>(i)].c_str(),"#35C8D9",0.f,0.f,1.f,std::move(tracks)));}int lock=3+static_cast<int>(target.size())*8;auto final=overlay("decode_target",target.c_str(),"#35C8D9",0.f,0.f,1.f,{t("opacity",{{0,0.f},{lock,0.f},{lock+2,1.f},{194,1.f},{209,0.f}},"linear")});d.textOverlays.push_back(std::move(final));return d;}
}
